window.KhaemenesScience9CumulativeQuestionBank=[{"unit":"Unit 05","domain":"Ecological organization","prompt":"Which term describes all populations of different species living and interacting in an area?","options":["Community.","Population.","Habitat.","Organism."],"answer":0,"explanation":"A community contains interacting populations of multiple species.","id":"legacy-q041","source":"unit-05","difficulty":"cumulative","type":"model"},{"unit":"Unit 05","domain":"Energy flow","prompt":"Why is less energy available at higher trophic levels?","options":["Matter stops cycling.","Organisms use and dissipate much energy through metabolism and heat transfer.","Energy atoms are destroyed.","Predators cannot digest food."],"answer":1,"explanation":"Energy is transferred and dissipated, so only part enters the next trophic level.","id":"legacy-q042","source":"unit-05","difficulty":"cumulative","type":"model"},{"unit":"Unit 05","domain":"Population ecology","prompt":"A population exceeds resource availability and then declines. Which factor most directly explains the decline?","options":["Creation of new energy.","Removal of all variation.","Density-dependent limitation such as competition for food.","Unlimited carrying capacity."],"answer":2,"explanation":"Competition, disease, and predation can intensify as density rises.","id":"legacy-q043","source":"unit-05","difficulty":"cumulative","type":"concept"},{"unit":"Unit 05","domain":"Biodiversity","prompt":"Species richness measures:","options":["The total biomass only.","The genetic sequence of one organism.","The age of an ecosystem.","The number of species present."],"answer":3,"explanation":"Richness counts species, while evenness describes relative abundances.","id":"legacy-q044","source":"unit-05","difficulty":"cumulative","type":"concept"},{"unit":"Unit 05","domain":"Natural selection","prompt":"Natural selection requires:","options":["Heritable variation and differences in reproductive success.","Individuals changing genes because they need to.","All organisms surviving equally.","No environmental influence."],"answer":0,"explanation":"Population traits change across generations when inherited variants affect reproductive success.","id":"legacy-q045","source":"unit-05","difficulty":"cumulative","type":"concept"},{"unit":"Unit 05","domain":"Evidence for evolution","prompt":"Which is direct empirical evidence used to reconstruct evolutionary relationships?","options":["The assumption that all similarities have one cause.","DNA sequence similarities and differences.","A philosophical preference.","A single unsupported story."],"answer":1,"explanation":"Genetic data are measured evidence; ancestry remains an inference supported by multiple evidence lines.","id":"legacy-q046","source":"unit-05","difficulty":"cumulative","type":"evidence"},{"unit":"Unit 05","domain":"Ecosystem resilience","prompt":"An ecosystem is generally more resilient when it has:","options":["No disturbance history.","No nutrient cycling.","Functional diversity and multiple pathways that can maintain processes.","Only one species performing each function."],"answer":2,"explanation":"Redundancy and diversity can support recovery, though resilience remains context-dependent.","id":"legacy-q047","source":"unit-05","difficulty":"cumulative","type":"model"},{"unit":"Unit 05","domain":"Conservation","prompt":"Which plan is strongest?","options":["Move organisms without permits.","Publish sensitive nest locations.","Choose an action without baseline data.","Protect habitat, involve affected communities, monitor outcomes, and revise using evidence."],"answer":3,"explanation":"Effective conservation combines ecological evidence, legal and cultural safeguards, monitoring, and adaptation.","id":"legacy-q048","source":"unit-05","difficulty":"cumulative","type":"model"},{"unit":"Unit 06","domain":"Atomic identity","prompt":"The atomic number equals the number of:","options":["Protons.","Neutrons plus electrons.","Neutrons only.","Electron shells."],"answer":0,"explanation":"Element identity is determined by proton number.","id":"legacy-q049","source":"unit-06","difficulty":"cumulative","type":"concept"},{"unit":"Unit 06","domain":"Particle counts","prompt":"A neutral atom has atomic number 12. How many electrons does it have?","options":["10.","12.","6.","24."],"answer":1,"explanation":"A neutral atom has equal numbers of protons and electrons.","id":"legacy-q050","source":"unit-06","difficulty":"cumulative","type":"quantitative"},{"unit":"Unit 06","domain":"Isotopes","prompt":"Isotopes of the same element differ in their number of:","options":["Valence shells only.","Nuclei.","Neutrons.","Protons."],"answer":2,"explanation":"Isotopes share proton number but have different neutron counts.","id":"legacy-q051","source":"unit-06","difficulty":"cumulative","type":"concept"},{"unit":"Unit 06","domain":"Ions","prompt":"An atom with 17 protons and 18 electrons has charge:","options":["+1.","0.","−17.","−1."],"answer":3,"explanation":"One extra electron gives a net charge of −1.","id":"legacy-q052","source":"unit-06","difficulty":"cumulative","type":"concept"},{"unit":"Unit 06","domain":"Relative atomic mass","prompt":"Why is a periodic-table atomic mass often not a whole number?","options":["It is an abundance-weighted average of naturally occurring isotopes.","Atoms contain fractional protons.","Every isotope has the same abundance.","Electrons have no mass."],"answer":0,"explanation":"The reported value reflects isotope masses and their relative abundance.","id":"legacy-q053","source":"unit-06","difficulty":"cumulative","type":"concept"},{"unit":"Unit 06","domain":"Electron arrangement","prompt":"For elements 1–20, group patterns are strongly related to:","options":["The number of compounds already discovered.","Outer-electron arrangements.","Neutron color.","Nuclear size only."],"answer":1,"explanation":"Recurring valence-electron patterns help explain chemical trends.","id":"legacy-q054","source":"unit-06","difficulty":"cumulative","type":"concept"},{"unit":"Unit 06","domain":"Periodic trends","prompt":"Which broad statement is accurate?","options":["Halogens are metals.","All elements in a period have identical properties.","Group 1 metals generally become more reactive down the group.","Noble gases are highly reactive."],"answer":2,"explanation":"Outer electrons are farther from the nucleus and more shielded down Group 1.","id":"legacy-q055","source":"unit-06","difficulty":"cumulative","type":"model"},{"unit":"Unit 06","domain":"Atomic models","prompt":"Why have atomic models changed over time?","options":["Atoms changed their laws.","Scientists preferred more complex drawings.","No experiments were involved.","New evidence required revision of earlier explanations."],"answer":3,"explanation":"Scientific models are revised when new observations are not adequately explained.","id":"legacy-q056","source":"unit-06","difficulty":"cumulative","type":"model"},{"unit":"Unit 07","domain":"Ionic bonding","prompt":"Ionic bonding is the electrostatic attraction between:","options":["Oppositely charged ions.","Neutral molecules only.","Two nuclei with no electrons.","Identical atoms sharing no particles."],"answer":0,"explanation":"Electron transfer can form cations and anions that attract in a lattice.","id":"legacy-q057","source":"unit-07","difficulty":"cumulative","type":"concept"},{"unit":"Unit 07","domain":"Covalent bonding","prompt":"A covalent bond involves:","options":["Destruction of valence electrons.","A shared pair of electrons between atoms.","A neutron transfer.","Only attraction between separate ions."],"answer":1,"explanation":"Shared electron density attracts both nuclei.","id":"legacy-q058","source":"unit-07","difficulty":"cumulative","type":"concept"},{"unit":"Unit 07","domain":"Formulae","prompt":"What is the neutral formula formed from Mg²⁺ and Cl⁻?","options":["MgCl.","Mg₂Cl₂.","MgCl₂.","Mg₂Cl."],"answer":2,"explanation":"Two chloride ions are needed to balance one magnesium ion.","id":"legacy-q059","source":"unit-07","difficulty":"cumulative","type":"concept"},{"unit":"Unit 07","domain":"Conservation","prompt":"Why must a chemical equation be balanced?","options":["Molecules must have equal masses individually.","Energy is never transferred.","Coefficients change element identities.","Atoms are rearranged but conserved in a closed chemical reaction."],"answer":3,"explanation":"Equal atom counts represent conservation of matter.","id":"legacy-q060","source":"unit-07","difficulty":"cumulative","type":"model"},{"unit":"Unit 07","domain":"Reaction energy","prompt":"In an exothermic reaction:","options":["The system transfers net energy to the surroundings.","The surroundings transfer net energy into the system.","No bonds change.","Temperature must always remain constant."],"answer":0,"explanation":"Exothermic reactions have lower-energy products relative to reactants under the stated conditions.","id":"legacy-q061","source":"unit-07","difficulty":"cumulative","type":"concept"},{"unit":"Unit 07","domain":"Reaction rate","prompt":"Why does increasing temperature often increase reaction rate?","options":["Products disappear.","Particles collide more frequently and a larger fraction have sufficient energy.","Atoms become larger.","Catalysts are automatically created."],"answer":1,"explanation":"Higher temperature changes collision frequency and energy distribution.","id":"legacy-q062","source":"unit-07","difficulty":"cumulative","type":"quantitative"},{"unit":"Unit 07","domain":"Catalysts","prompt":"A catalyst increases reaction rate by:","options":["Being consumed as the main reactant.","Raising atomic number.","Providing an alternative pathway with lower activation energy.","Increasing the equilibrium amount of every product."],"answer":2,"explanation":"A catalyst changes the reaction pathway and is regenerated overall.","id":"legacy-q063","source":"unit-07","difficulty":"cumulative","type":"concept"},{"unit":"Unit 07","domain":"Equilibrium","prompt":"Dynamic equilibrium in a closed system means:","options":["All reactions stop.","Reactant and product concentrations must be equal.","The container contains only products.","Forward and reverse reactions continue at equal rates."],"answer":3,"explanation":"Macroscopic concentrations remain constant while microscopic reactions continue.","id":"legacy-q064","source":"unit-07","difficulty":"cumulative","type":"model"},{"id":"u05-q-q01","domain":"Ecological organization","prompt":"Which level includes interacting populations and abiotic conditions?","options":["Ecosystem","Species","Organism","Population"],"answer":0,"explanation":"An ecosystem includes a community and its abiotic environment.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q02","domain":"Niche","prompt":"A niche is best described as:","options":["Only the geographic location of an organism","The organism’s role, resource use, tolerances, timing, and interactions","A permanent population size","A fossil classification"],"answer":1,"explanation":"A niche is broader than habitat and includes ecological function and requirements.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q03","domain":"Food webs","prompt":"What does an arrow from seed to mouse indicate?","options":["Both have identical roles","The seed hunts the mouse","Transfer of matter and energy from seed to mouse","The mouse produces the seed"],"answer":2,"explanation":"The consumer receives matter and chemical energy from the resource.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q04","domain":"Energy transfer","prompt":"If 5,000 kJ is available to one trophic level and 600 kJ to the next, efficiency is:","options":["83.3%","120%","8.3%","12%"],"answer":3,"explanation":"600 ÷ 5,000 × 100 = 12%.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q05","domain":"Matter cycles","prompt":"Which process moves carbon from organisms to atmospheric carbon dioxide?","options":["Cellular respiration","Sedimentation only","Photosynthesis only","Nitrogen fixation"],"answer":0,"explanation":"Cellular respiration releases carbon dioxide.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q06","domain":"Biodiversity","prompt":"Two sites have the same species richness. Which additional information is needed to compare evenness?","options":["The age of the observer","Relative abundance of each species","Only the site names","Only total land area"],"answer":1,"explanation":"Evenness depends on how balanced species abundances are.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q07","domain":"Sampling","prompt":"Why must sampling effort be recorded in a biodiversity survey?","options":["It eliminates seasonal change","It replaces species identification","More effort can detect more organisms and affect comparisons","It proves every species was found"],"answer":2,"explanation":"Different effort can create apparent differences unrelated to actual diversity.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"evidence"},{"id":"u05-q-q08","domain":"Population density","prompt":"A count of 900 organisms across 60 hectares equals:","options":["54 per hectare","960 per hectare","10 per hectare","15 per hectare"],"answer":3,"explanation":"900 ÷ 60 = 15 per hectare.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"quantitative"},{"id":"u05-q-q09","domain":"Population models","prompt":"Why is carrying capacity not necessarily constant?","options":["It changes with environmental resources and pressures","It is set only by body size","It cannot be estimated","It equals zero for all predators"],"answer":0,"explanation":"Resources, habitat, climate, disease, interactions, and human actions change capacity.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q10","domain":"Interactions","prompt":"Which interaction is commonly represented +/+?","options":["Parasitism","Mutualism","Competition","Predation"],"answer":1,"explanation":"Mutualism describes an average benefit to both partners under stated conditions.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q11","domain":"Succession","prompt":"Secondary succession differs from primary succession because secondary succession usually begins with:","options":["Only volcanic rock and no soil","No matter present","Existing soil or biological legacies","No organisms ever returning"],"answer":2,"explanation":"Soil, seeds, roots, microbes, or survivors often persist after secondary disturbance.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q12","domain":"Conservation","prompt":"Which conservation plan is strongest?","options":["One that hides uncertainty","One with no measurable target","One based only on popularity","One with a baseline, causal pressure, indicator, community rights, and revision rule"],"answer":3,"explanation":"Transparent goals, indicators, causes, rights, and adaptive revision support evaluation.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"model"},{"id":"u05-q-q14","domain":"Resistance","prompt":"Which statement about antimicrobial resistance is correct?","options":["A person’s body evolves resistance to the drug","Microbial populations can change in the frequency of resistant variants","Antibiotics intentionally teach bacteria","Resistance proves every historical ancestry claim"],"answer":1,"explanation":"Selection can increase resistant microbial variants; one example does not settle every origins claim.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"quantitative"},{"id":"u05-q-q15","domain":"Terminology","prompt":"In standard biology, macroevolution includes:","options":["Any personal worldview conclusion","Only changes within one lifetime","Speciation, extinction, and diversification at or above species level","An individual suddenly producing an unrelated organism"],"answer":2,"explanation":"Macroevolution is defined as patterns at or above the species level.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q16","domain":"Species concepts","prompt":"Why can fossil species boundaries be uncertain?","options":["All fossils are identical","Geological context is irrelevant","Fossils never contain anatomy","Reproductive compatibility cannot usually be tested and variation may overlap"],"answer":3,"explanation":"Fossil classification relies on preserved anatomy and context rather than direct breeding tests.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q17","domain":"Equid record","prompt":"Modern scientific diagrams of equid history are usually branching because:","options":["Multiple equid forms coexisted and many branches became extinct","Every fossil forms one direct ladder","Only one horse species ever existed","Branching eliminates uncertainty"],"answer":0,"explanation":"The evidence is interpreted as diversification with contemporaneous and extinct branches.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q18","domain":"Evidence classification","prompt":"A fossil’s geological location is an observation; calling it a direct ancestor is:","options":["Another measurement","A historical inference","A unit conversion","A trophic role"],"answer":1,"explanation":"Ancestry is inferred from multiple lines of evidence.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"evidence"},{"id":"u05-q-q19","domain":"Worldviews","prompt":"How should student worldview positions be graded in this unit?","options":["By whether they adopt one required belief","By family religion","By accuracy, evidence classification, reasoning, source fairness, and respect","By majority vote"],"answer":2,"explanation":"The curriculum evaluates literacy and reasoning, not compelled belief.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-q-q20","domain":"Stewardship","prompt":"Which statement identifies possible common ground across origins views?","options":["Evidence should be hidden","Conservation requires agreement on every origins question","No responsibility for ecosystems","Protection of biodiversity and responsible stewardship can be supported from different worldviews"],"answer":3,"explanation":"People with different origins views can support evidence-based stewardship.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz","type":"concept"},{"id":"u05-a-a01","domain":"Organization","prompt":"Which sequence increases in ecological scale?","options":["Organism → population → community → ecosystem","Population → organism → ecosystem → community","Community → organism → population → ecosystem","Ecosystem → community → population → organism"],"answer":0,"explanation":"Individuals form populations; interacting populations form communities; communities plus abiotic environment form ecosystems.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a02","domain":"Observation and inference","prompt":"Which statement is a direct observation?","options":["The ecosystem will collapse","Twelve individuals were counted in a 10 m transect","The organism evolved this trait because it needed it","Shade caused the species decline"],"answer":1,"explanation":"A documented count is an observation; causal and historical statements are inferences.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a03","domain":"Habitat and niche","prompt":"Which statement correctly distinguishes habitat and niche?","options":["Niche is only body size","Habitat is a genome","Habitat is location; niche includes role and resource use","They are always identical"],"answer":2,"explanation":"Habitat describes where an organism lives; niche includes its ecological role and requirements.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a04","domain":"Trophic roles","prompt":"Which is a detritivore?","options":["Oak tree","Green algae","Hawk","Earthworm ingesting leaf fragments"],"answer":3,"explanation":"A detritivore ingests detrital particles.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a05","domain":"Food-web effects","prompt":"Why can removal of one species affect several others?","options":["Food webs contain direct and indirect interactions","Every species eats every other species","Energy cycles forever","Abiotic conditions never matter"],"answer":0,"explanation":"Networked interactions can transmit effects through several pathways.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a06","domain":"Energy calculation","prompt":"A trophic level receives 320 kJ from a preceding level with 4,000 kJ. Efficiency is:","options":["6%","8%","12.5%","80%"],"answer":1,"explanation":"320 ÷ 4,000 × 100 = 8%.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"quantitative"},{"id":"u05-a-a08","domain":"Matter cycles","prompt":"Which process converts atmospheric nitrogen into biologically available forms?","options":["Respiration","Evaporation","Combustion","Nitrogen fixation"],"answer":3,"explanation":"Nitrogen fixation converts N₂ into compounds that enter biological cycles.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a09","domain":"Matter and energy","prompt":"Which statement is accurate?","options":["Matter cycles while energy flows through and dissipates","Neither crosses ecosystem boundaries","Energy cycles and matter flows one way","Both disappear"],"answer":0,"explanation":"Matter is conserved and recycled, while usable energy is dissipated.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a10","domain":"Diversity calculation","prompt":"A sample contains counts 4, 4, 4, and 4 for four species. Compared with counts 13, 1, 1, and 1, the first sample has:","options":["Lower richness","The same richness and greater evenness","No biodiversity","Fewer total organisms"],"answer":1,"explanation":"Both contain four species and 16 organisms, but the first is more even.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"quantitative"},{"id":"u05-a-a11","domain":"Survey design","prompt":"Which practice best protects threatened species?","options":["Publish exact nest coordinates","Handle every organism for identification","Avoid revealing precise sensitive locations and use non-contact records","Collect specimens without permits"],"answer":2,"explanation":"Location privacy and non-disturbance reduce risk.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a12","domain":"Population change","prompt":"A population changes from 800 to 680. What is the percentage change?","options":["−12%","15%","85%","−15%"],"answer":3,"explanation":"(680−800) ÷ 800 × 100 = −15%.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"quantitative"},{"id":"u05-a-a13","domain":"Mark–recapture","prompt":"Which condition violates a simple mark–recapture assumption?","options":["Marked animals become much easier to capture than unmarked animals","The study interval is short","Marks remain identifiable","Marked individuals mix into the population"],"answer":0,"explanation":"Different capture probability biases the ratio.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"quantitative"},{"id":"u05-a-a14","domain":"Population growth","prompt":"Exponential growth assumes approximately:","options":["Only emigration","Constant proportional growth with no immediate resource limit","A fixed carrying capacity already reached","No births"],"answer":1,"explanation":"Exponential models approximate unrestricted proportional growth.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"quantitative"},{"id":"u05-a-a15","domain":"Predator–prey evidence","prompt":"A predator and prey time series shows opposite trends. What additional evidence strengthens a causal explanation?","options":["A personal preference","Removal of inconvenient years","Feeding records, prey survival, vegetation, disease, weather, and alternative-factor analysis","A single graph title"],"answer":2,"explanation":"Mechanistic and comparative evidence helps test causation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a16","domain":"Interactions","prompt":"Which interaction is +/−?","options":["Competition","Commensalism","Mutualism","Predation"],"answer":3,"explanation":"A predator benefits while prey is harmed.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a17","domain":"Resilience","prompt":"Ecosystem resilience refers most closely to:","options":["Capacity to absorb disturbance while retaining or reorganizing key functions","Having the most species in every sample","Eliminating all fire","Never changing"],"answer":0,"explanation":"Resilience concerns persistence or recovery of functions despite change.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a18","domain":"Conservation evidence","prompt":"Which result is an outcome rather than a projection?","options":["A proposal promises recovery","A monitored population increased from 200 to 260 after intervention, with stated method","A slogan says the plan will work","A model predicts a 20% increase"],"answer":1,"explanation":"A measured post-intervention record is an observed outcome, though causal evaluation still needs design and comparison.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a19","domain":"Selection","prompt":"Which statement avoids teleological language?","options":["The drug created only useful mutations","Bacteria became resistant because they wanted to survive","Antibiotic exposure favored resistant variants that left more descendants","Every bacterium intentionally changed its DNA"],"answer":2,"explanation":"Selection changes variant frequencies; it does not require purposeful mutation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a20","domain":"Variation","prompt":"Which process creates new alleles?","options":["Selection alone","Independent assortment alone","Migration alone","Mutation"],"answer":3,"explanation":"Mutation changes DNA sequence and can create a new allele.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a21","domain":"Microevolution","prompt":"A measured allele-frequency shift across generations is commonly classified as:","options":["Microevolution","A theological proof","A fossil ancestor","No biological change"],"answer":0,"explanation":"Microevolution includes measurable inherited-frequency changes in populations.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a22","domain":"Speciation","prompt":"Which provides direct evidence relevant to speciation in living populations?","options":["One individual changing species during life","Reduced interbreeding or reproductive compatibility between diverging populations","A drawing without data","A claim that no boundaries exist"],"answer":1,"explanation":"Reproductive isolation is central to many species concepts.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a23","domain":"Macroevolution definition","prompt":"Which statement is consistent with the standard biological use of macroevolution?","options":["It is identical to abiogenesis","It requires a sudden jump by one individual","It includes speciation and diversification across lineages","It means acquired traits during one lifetime"],"answer":2,"explanation":"Macroevolution refers to patterns at or above the species level and is not the origin of life.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u05-a-a24","domain":"Fossils","prompt":"Which statement about fossil evidence is accurate?","options":["Every fossil includes its family tree","Fossils cannot be measured","Fossil classifications never change","Fossils can preserve anatomy and context but rarely identify a direct parent–descendant pair"],"answer":3,"explanation":"Anatomy and context are observed; ancestry is reconstructed and classifications may be revised.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a25","domain":"Equids","prompt":"Why is a ladder model of horse evolution misleading?","options":["The record is interpreted as branching, with coexisting forms and extinct side branches","Modern horses have many functional toes","DNA proves every fossil is a parent","No equids existed"],"answer":0,"explanation":"Equid diversity is not a single uninterrupted march.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"model"},{"id":"u05-a-a26","domain":"Evidence levels","prompt":"Which sequence moves from most direct to most interpretive?","options":["Worldview conclusion → measurement → specimen","Specimen → measurement → classification → ancestry inference → worldview conclusion","Ancestry inference → specimen → measurement","Classification → specimen → observation"],"answer":1,"explanation":"Evidence should be separated from progressively broader interpretation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a28","domain":"Source evaluation","prompt":"How should an advocacy source be used?","options":["As proof that opposing evidence does not exist","Without identifying its perspective","As direct fossil evidence","As a primary source for what that organization argues, checked against underlying data"],"answer":3,"explanation":"Advocacy sources accurately document viewpoints, but scientific claims must be traced to data and methods.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a29","domain":"Fair assessment","prompt":"Which student response should receive the stronger score?","options":["One that accurately classifies evidence, fairly represents alternatives, and supports a reasoned conclusion","One that attacks another student’s faith","One that refuses to cite sources","One that repeats a preferred conclusion but misstates evidence"],"answer":0,"explanation":"Assessment is based on literacy, evidence, reasoning, and respectful representation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"evidence"},{"id":"u05-a-a30","domain":"Stewardship","prompt":"A strong stewardship proposal includes:","options":["A hidden decision process","Target, baseline, action, indicator, community consideration, uncertainty, and revision rule","Only a moral slogan","No monitoring"],"answer":1,"explanation":"A testable and accountable plan defines evidence, action, rights, and adaptation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment","type":"concept"},{"id":"u06-q-q01","domain":"Matter","prompt":"Which statement distinguishes an element from a compound?","options":["An element contains one type of atom; a compound contains elements chemically combined in fixed proportions","Compounds cannot be pure","Elements always separate physically","An element contains one proton only"],"answer":0,"explanation":"Elements have one atomic number; compounds have bonded elements in fixed ratios.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q02","domain":"Atomic model","prompt":"Rutherford’s scattering evidence most directly supported:","options":["Atoms are indivisible spheres","Positive charge and most mass are concentrated in a small nucleus","Electrons are positive","Atoms contain no empty space"],"answer":1,"explanation":"Rare strong deflections supported a small dense positive nucleus.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"evidence"},{"id":"u06-q-q03","domain":"Particles","prompt":"Which particle has relative charge 0 and relative mass about 1?","options":["Ion","Electron","Neutron","Proton"],"answer":2,"explanation":"A neutron is neutral and has mass close to one atomic mass unit.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q04","domain":"Atomic number","prompt":"An atom with 15 protons is always:","options":["Sulfur","Silicon","Carbon","Phosphorus"],"answer":3,"explanation":"Atomic number 15 identifies phosphorus.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q05","domain":"Mass number","prompt":"An isotope has 17 protons and 20 neutrons. Its mass number is:","options":["37","3","17","20"],"answer":0,"explanation":"Mass number = 17 + 20 = 37.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q06","domain":"Charge","prompt":"A calcium atom loses two electrons. The ion has charge:","options":["1+","2+","2−","1−"],"answer":1,"explanation":"Losing two electrons gives 2+.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q07","domain":"Isotopes","prompt":"Which pair represents isotopes of the same element?","options":["³⁵Cl and ⁴⁰Ar","¹H and ⁴He","¹²C and ¹⁴C","²³Na and ²⁴Mg"],"answer":2,"explanation":"Both carbon atoms have six protons.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q08","domain":"Atomic weight","prompt":"A weighted atomic mass must use:","options":["Atomic number divided by neutrons","Electron number plus charge","Only the largest mass number","Isotope mass multiplied by fractional abundance, summed"],"answer":3,"explanation":"Relative atomic mass is an abundance-weighted mean.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q09","domain":"Shells","prompt":"Which is the shell configuration of calcium?","options":["2,8,8,2","2,8,10","2,8,7,3","20"],"answer":0,"explanation":"Twenty electrons distribute as 2,8,8,2.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q10","domain":"Valence","prompt":"Which element has seven outer-shell electrons?","options":["Magnesium","Chlorine","Argon","Sodium"],"answer":1,"explanation":"Chlorine is Group 17.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q11","domain":"Period","prompt":"An element with configuration 2,8,3 is in which period?","options":["1","2","3","13"],"answer":2,"explanation":"Three occupied shells place it in Period 3.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q12","domain":"Group","prompt":"Which pair belongs to Group 2?","options":["F and Cl","Ne and Ar","Li and Na","Be and Mg"],"answer":3,"explanation":"Beryllium and magnesium have two outer electrons.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q13","domain":"Periodic order","prompt":"What uniquely fixes an element’s position in atomic-number order?","options":["Proton count","Average neutron count","Physical state","Discovery date"],"answer":0,"explanation":"Proton count is atomic number.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q14","domain":"Group 1","prompt":"Which is the safest way to study alkali-metal reactivity?","options":["Put potassium in water at home","Use verified datasets or a qualified recorded demonstration","Touch sodium","Mix unknown metals with acid"],"answer":1,"explanation":"Reactive alkali metals require specialist controls.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q15","domain":"Group 17","prompt":"Which statement is accurate for halogens down Group 17?","options":["They form 2+ ions","Outer-electron number increases","Reactivity generally decreases","All are gases"],"answer":2,"explanation":"Reactivity generally decreases down the group.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q16","domain":"Noble gases","prompt":"Which element has a filled second shell?","options":["Sodium","Oxygen","Fluorine","Neon"],"answer":3,"explanation":"Neon has 2,8.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q17","domain":"Spectra","prompt":"Why can line spectra help identify elements?","options":["Each element has characteristic allowed energy differences","All emit the same wavelengths","Spectra show neutron positions","Only compounds emit light"],"answer":0,"explanation":"Characteristic energy differences produce characteristic lines.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q18","domain":"Model limits","prompt":"Which statement is most responsible?","options":["The Bohr picture is exact","Models should be used within evidence and scale limitations","Diagrams are photographs","Electron paths are always exact"],"answer":1,"explanation":"Scientific models are useful representations with limits.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"model"},{"id":"u06-q-q19","domain":"Data","prompt":"An atomic-weight interval for an element indicates:","options":["The table is unordered","Proton count varies","Normal materials can have isotope-composition variation","The element has no isotopes"],"answer":2,"explanation":"Natural isotope ratios can vary.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-q-q20","domain":"Prediction","prompt":"An element has two occupied shells and one outer electron. Which fits?","options":["Sodium","Magnesium","Fluorine","Lithium"],"answer":3,"explanation":"Lithium has configuration 2,1.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz","type":"concept"},{"id":"u06-a-a01","domain":"Classification","prompt":"Which sample is a compound?","options":["Pure sodium chloride","Air","Copper metal","Oxygen gas"],"answer":0,"explanation":"Sodium chloride contains elements chemically combined in a fixed ratio.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a02","domain":"Atomic evidence","prompt":"Which observation led Thomson to infer negatively charged particles within atoms?","options":["Atoms were visible in a microscope","Cathode rays were deflected by electric and magnetic fields","Gold foil produced alpha particles","All gases had identical spectra"],"answer":1,"explanation":"Cathode-ray deflection supported negatively charged subatomic particles.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"evidence"},{"id":"u06-a-a03","domain":"Atomic evidence","prompt":"In Rutherford scattering, most alpha particles passed through foil. This supports the inference that atoms are:","options":["Made only of electrons","Without nuclei","Mostly empty space at that scale","Uniform solid spheres"],"answer":2,"explanation":"Most particles encountered no concentrated mass or charge.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"evidence"},{"id":"u06-a-a04","domain":"Model revision","prompt":"Why did atomic models change over time?","options":["Scientists agreed never to test them","The proton count changed historically","Models are personal opinions only","New evidence exposed limitations and supported revised models"],"answer":3,"explanation":"Scientific models are revised when new evidence requires better explanations.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"model"},{"id":"u06-a-a05","domain":"Particle charge","prompt":"Which set of relative charges is correct for proton, neutron, electron?","options":["+1, 0, −1","−1, 0, +1","+1, −1, 0","0, +1, −1"],"answer":0,"explanation":"Proton +1, neutron 0, electron −1.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a06","domain":"Particle mass","prompt":"Which contributes least to an atom’s mass?","options":["Neutron","Electron","Nucleus","Proton"],"answer":1,"explanation":"Electron mass is much smaller than proton or neutron mass.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a07","domain":"Composition","prompt":"A neutral atom contains 8 protons and 10 neutrons. Which statement is correct?","options":["It is oxygen-10 with 18 electrons","It is neon-18 with 10 electrons","It is oxygen-18 with 8 electrons","It is fluorine-18 with 8 electrons"],"answer":2,"explanation":"Atomic number 8 is oxygen; mass number 18; neutrality gives 8 electrons.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a08","domain":"Ion charge","prompt":"A particle has 13 protons and 10 electrons. It is:","options":["Al³⁻","Ne³⁺","Mg²⁺","Al³⁺"],"answer":3,"explanation":"Atomic number 13 is aluminium; three fewer electrons gives 3+.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a09","domain":"Nuclear notation","prompt":"In the notation ³⁹₁₉K, the lower number represents:","options":["Atomic number","Mass number","Neutron number","Electron charge"],"answer":0,"explanation":"The subscript is atomic number.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a10","domain":"Isotopes","prompt":"Which property differs between neutral chlorine-35 and chlorine-37 atoms?","options":["Electron arrangement","Neutron number","Element identity","Proton number"],"answer":1,"explanation":"They differ in neutron number.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a11","domain":"Weighted average","prompt":"An element has isotope masses 10 and 11 with abundances 20% and 80%. Its weighted mass is:","options":["10.2","10.5","10.8","21"],"answer":2,"explanation":"10(0.20)+11(0.80)=10.8.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"quantitative"},{"id":"u06-a-a12","domain":"Abundance","prompt":"Three isotope fractions are 0.79, 0.10, and 0.11. Their total is:","options":["1.10","79","0.90","1.00"],"answer":3,"explanation":"The fractions sum to 1.00.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"quantitative"},{"id":"u06-a-a13","domain":"Atomic weight","prompt":"Which statement about standard atomic weight is most accurate?","options":["It may be a weighted value or interval reflecting natural isotope composition","It equals the proton number","It is identical for every isotope","It is always a whole-number mass number"],"answer":0,"explanation":"Standard atomic weights summarize representative isotope masses and abundances.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a14","domain":"Electron configuration","prompt":"Which configuration belongs to aluminium?","options":["2,7","2,8,3","2,8,2","2,8,4"],"answer":1,"explanation":"Aluminium has atomic number 13.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a15","domain":"Ion configuration","prompt":"Which species has configuration 2,8?","options":["Cl⁻","K⁺","Na⁺","Na atom"],"answer":2,"explanation":"Na⁺ has 10 electrons; Cl⁻ and K⁺ have 18.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a16","domain":"Period","prompt":"Which element is in Period 4 among the first 20?","options":["Sodium","Argon","Chlorine","Potassium"],"answer":3,"explanation":"Potassium has four occupied shells.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a17","domain":"Group","prompt":"Which pair has related chemical properties because both have one outer electron?","options":["Li and K","O and Ne","Mg and Cl","C and Ar"],"answer":0,"explanation":"Lithium and potassium are Group 1.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a18","domain":"Periodic history","prompt":"Mendeleev’s table was historically powerful partly because it:","options":["Rejected repeating properties","Left gaps and predicted properties of undiscovered elements","Was ordered by exact neutron count","Contained all 118 modern elements"],"answer":1,"explanation":"Its gaps enabled testable predictions.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a19","domain":"Modern order","prompt":"Why is atomic number superior to relative atomic mass as the defining order?","options":["Neutrons determine chemistry alone","Atomic number is always larger","It uniquely identifies nuclear charge and resolves mass-order anomalies","Atomic mass is never measured"],"answer":2,"explanation":"Proton number fixes identity and corrects mass-order anomalies.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a20","domain":"Across-period trend","prompt":"Across Period 3, which general change occurs?","options":["Atomic number decreases","Occupied shells increase from three to eight","All elements form +1 ions","Metallic character decreases toward nonmetals"],"answer":3,"explanation":"Metallic character generally declines across the period.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a21","domain":"Group 1","prompt":"Which property generally increases from lithium to potassium?","options":["Reactivity with water","Melting point","Outer-electron count","Ion charge magnitude"],"answer":0,"explanation":"Group 1 reactivity generally increases down the group.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a22","domain":"Group 17","prompt":"Which property generally decreases from fluorine to iodine?","options":["Density","Reactivity","Number of occupied shells","Atomic number"],"answer":1,"explanation":"Halogen reactivity generally decreases down the group.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a23","domain":"Group 18","prompt":"Which is a noble gas?","options":["Potassium","Calcium","Argon","Chlorine"],"answer":2,"explanation":"Argon is Group 18.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a24","domain":"Prediction","prompt":"An element in Group 2, Period 3 is:","options":["Calcium","Sodium","Aluminium","Magnesium"],"answer":3,"explanation":"Magnesium is in Period 3 and Group 2.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a25","domain":"Prediction","prompt":"Which common ion is predicted for configuration 2,8,7?","options":["1− after gaining one electron","1+ after losing one proton","2− after losing two electrons","No possible ion"],"answer":0,"explanation":"The simple model predicts gain of one electron.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a26","domain":"Spectra","prompt":"A line spectrum contains discrete wavelengths because:","options":["Visible light has no energy","Electron energies occur in allowed states and transitions have specific energy differences","The nucleus emits every wavelength","All atoms have one electron"],"answer":1,"explanation":"Specific transitions produce photons with specific energies.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a27","domain":"Safety","prompt":"Which investigation is appropriate without a specialist laboratory?","options":["React potassium with water","Open a radioactive device","Analyze published emission spectra","Burn unknown salts indoors"],"answer":2,"explanation":"Published spectra can be analyzed safely.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"concept"},{"id":"u06-a-a28","domain":"Source quality","prompt":"Which source is strongest for a chlorine isotope calculation?","options":["An anonymous post","A movie prop","A product advertisement","A NIST isotope table with definitions and provenance"],"answer":3,"explanation":"A traceable reference database supplies definitions and provenance.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"evidence"},{"id":"u06-a-a29","domain":"Model limits","prompt":"Which statement avoids overstating a model?","options":["The shell model predicts useful outer-electron patterns but does not depict literal fixed paths","Electrons are colored balls exactly as shown","The nucleus is the same size as the diagram","A model cannot be revised"],"answer":0,"explanation":"The shell model is useful but not literal.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"model"},{"id":"u06-a-a30","domain":"Evidence reasoning","prompt":"A responsible periodic-trend conclusion should:","options":["Treat every group as identical","Use measured data, state the range, identify exceptions, and avoid claiming an absolute law","Discard values that do not fit","Use only one element"],"answer":1,"explanation":"Trend claims require defined scope and limitations.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment","type":"evidence"},{"id":"u07-q-q01","domain":"Bonding","prompt":"Which description best fits ionic bonding in NaCl?","options":["Attraction among Na⁺ and Cl⁻ ions in a lattice","One isolated NaCl molecule only","Shared protons","No electrostatic forces"],"answer":0,"explanation":"NaCl forms an extended ionic lattice.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q02","domain":"Formula","prompt":"What is the correct formula for calcium oxide?","options":["Ca₂O₂","CaO","Ca₂O","CaO₂"],"answer":1,"explanation":"Ca²⁺ and O²⁻ combine in a 1:1 ratio.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q03","domain":"Formula","prompt":"What is the correct formula for aluminium chloride?","options":["AlCl","AlCl₂","AlCl₃","Al₃Cl"],"answer":2,"explanation":"Three Cl⁻ ions balance Al³⁺.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q04","domain":"Covalent","prompt":"Which substance consists of simple covalent molecules?","options":["Sodium chloride","Copper","Diamond","Carbon dioxide"],"answer":3,"explanation":"CO₂ contains discrete molecules.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q05","domain":"Structure","prompt":"Which substance contains a giant metallic lattice?","options":["Copper","Methane","Water","Sodium chloride"],"answer":0,"explanation":"Copper is metallic.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"model"},{"id":"u07-q-q06","domain":"Graphite","prompt":"Which feature supports graphite’s conductivity?","options":["No bonding","Delocalised electrons","Mobile chloride ions","Water molecules"],"answer":1,"explanation":"Electrons can move within the layers.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q07","domain":"Polarity","prompt":"Which bond is expected to be most polar among these?","options":["C–C","Cl–Cl","H–F","H–H"],"answer":2,"explanation":"H–F has the largest electronegativity difference of the options.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q08","domain":"Formula mass","prompt":"Using Ar values Na=23 and Cl=35.5, Mr of NaCl is:","options":["81.5","23","35.5","58.5"],"answer":3,"explanation":"23 + 35.5 = 58.5.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"quantitative"},{"id":"u07-q-q09","domain":"Equation","prompt":"Which equation is balanced?","options":["N₂ + 3H₂ → 2NH₃","2N₂ + H₂ → 2NH₃","N₂ + H₂ → NH₃","N₂ + 2H₂ → 2NH₃"],"answer":0,"explanation":"Both sides contain two N and six H atoms.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q10","domain":"Subscripts","prompt":"Why must subscripts not be changed to balance an equation?","options":["It changes temperature","Changing a subscript changes the substance","Subscripts have no meaning","Only gases use subscripts"],"answer":1,"explanation":"A different subscript represents a different composition.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q11","domain":"State symbols","prompt":"Which symbol identifies a solid?","options":["(g)","(aq)","(s)","(l)"],"answer":2,"explanation":"(s) denotes solid.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q12","domain":"Conservation","prompt":"A balanced equation demonstrates conservation of:","options":["Temperature","Color","Volume in every reaction","Each type of atom"],"answer":3,"explanation":"Atom counts match across the reaction.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"model"},{"id":"u07-q-q13","domain":"Evidence","prompt":"Which observation is strongest evidence for a precipitate reaction?","options":["A new insoluble solid appears","The container remains clear","A liquid changes shape","A solid is crushed"],"answer":0,"explanation":"A precipitate is an insoluble solid product.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"evidence"},{"id":"u07-q-q14","domain":"Energy","prompt":"Which reaction from the supplied table is endothermic?","options":["Formation of ammonia","CaCO₃ → CaO + CO₂","CH₄ combustion","Formation of water"],"answer":1,"explanation":"The listed calcium-carbonate decomposition has positive ΔH.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q15","domain":"Pathway","prompt":"On an energy diagram, activation energy is measured from:","options":["Reactants to products only","Temperature to pressure","Reactant energy to the pathway peak","Products to zero"],"answer":2,"explanation":"The barrier is the difference between reactants and the transition-state peak.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q16","domain":"Catalyst","prompt":"What remains unchanged when a catalyst is added?","options":["Activation energy","Reaction pathway","Rate","Overall ΔH"],"answer":3,"explanation":"A catalyst lowers the barrier but does not change reactant/product energy difference.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-q-q17","domain":"Rate","prompt":"Which change generally increases reaction rate for a solid reactant?","options":["Increasing surface area","Lowering concentration","Cooling the system","Removing a catalyst"],"answer":0,"explanation":"Greater surface area increases accessible collision sites.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"quantitative"},{"id":"u07-q-q18","domain":"Rate data","prompt":"A shorter completion time for the same amount of reaction usually indicates:","options":["More atoms created","A faster average rate","A slower rate","No reaction"],"answer":1,"explanation":"The same change occurring in less time is faster.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"quantitative"},{"id":"u07-q-q19","domain":"Equilibrium","prompt":"Which statement is true at equilibrium?","options":["Reactant concentration is always zero","A catalyst shifts the position","Concentrations are constant but not necessarily equal","The forward reaction stops"],"answer":2,"explanation":"Equal forward and reverse rates keep concentrations constant.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"model"},{"id":"u07-q-q20","domain":"Safety","prompt":"Which activity is appropriate for home or ordinary classroom use with adult approval and goggles?","options":["Burning magnesium without a lab","Mixing household cleaners","Heating a sealed gas-producing reaction","Timing an effervescent tablet in water"],"answer":3,"explanation":"The other activities present serious hazards.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz","type":"concept"},{"id":"u07-a-a01","domain":"Bonding","prompt":"Which force is central to ionic bonding?","options":["Electrostatic attraction between opposite charges","Gravity between molecules","Magnetic attraction between neutrons","Friction"],"answer":0,"explanation":"Ionic bonding is electrostatic attraction.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a02","domain":"Bonding","prompt":"Which statement best describes a covalent bond?","options":["A physical mixture","A shared electron pair between atoms","A transferred neutron","A moving cation"],"answer":1,"explanation":"The introductory covalent model uses shared electron pairs.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a03","domain":"Formula","prompt":"What formula results from K⁺ and O²⁻?","options":["K₂O₂","KO","K₂O","KO₂"],"answer":2,"explanation":"Two K⁺ ions balance one O²⁻ ion.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a04","domain":"Formula","prompt":"What formula results from Al³⁺ and SO₄²⁻?","options":["Al₃(SO₄)₂","AlSO₄","Al₂SO₄","Al₂(SO₄)₃"],"answer":3,"explanation":"Two Al³⁺ give +6 and three sulfate ions give −6.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a05","domain":"Formula","prompt":"Why are parentheses used in Ca(OH)₂?","options":["Two hydroxide ions are present","Calcium is repeated","The compound is molecular","The charge is zero before bonding"],"answer":0,"explanation":"The parentheses group the repeated polyatomic ion.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a06","domain":"Structure","prompt":"Which substance is expected to conduct when molten but not when solid?","options":["Carbon dioxide","Sodium chloride","Methane","Diamond"],"answer":1,"explanation":"Molten ionic compounds have mobile ions.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"model"},{"id":"u07-a-a07","domain":"Structure","prompt":"Which property is characteristic of many simple molecular substances?","options":["Malleability","Giant lattices in every case","Low melting and boiling points","Conductivity from mobile ions in the solid"],"answer":2,"explanation":"Weak intermolecular attractions often give low phase-change temperatures.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"model"},{"id":"u07-a-a08","domain":"Structure","prompt":"Why is diamond hard?","options":["It contains mobile ions","Its molecules slide easily","It is metallic","Its atoms form a three-dimensional covalent network"],"answer":3,"explanation":"Many strong bonds extend through the network.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"model"},{"id":"u07-a-a09","domain":"Structure","prompt":"Why is copper conductive?","options":["Delocalised electrons can move through the metallic structure","Copper dissolves into ions in air","It contains water","Its bonds are absent"],"answer":0,"explanation":"Mobile delocalised electrons carry charge.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"model"},{"id":"u07-a-a10","domain":"Polarity","prompt":"Which statement distinguishes bond polarity from molecular polarity?","options":["Molecules have no geometry","A molecule’s shape can cause bond dipoles to cancel or reinforce","They are always identical","Only ions have polarity"],"answer":1,"explanation":"Whole-molecule polarity depends on both bond dipoles and arrangement.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a11","domain":"Formula mass","prompt":"Using C=12 and O=16, Mr of CO₂ is:","options":["28","32","44","56"],"answer":2,"explanation":"12 + 2(16) = 44.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"quantitative"},{"id":"u07-a-a12","domain":"Notation","prompt":"In 2H₂O, the coefficient 2 indicates:","options":["Two oxygen atoms per molecule","A new substance H₄O₂","A charge","Two water molecules or formula units in the represented ratio"],"answer":3,"explanation":"The coefficient multiplies the entire formula.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a13","domain":"Equation","prompt":"Which equation balances aluminium oxide formation?","options":["4Al + 3O₂ → 2Al₂O₃","Al₂ + O₃ → Al₂O₃","Al + O₂ → Al₂O₃","2Al + O₂ → Al₂O₃"],"answer":0,"explanation":"Four Al and six O atoms appear on both sides.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"model"},{"id":"u07-a-a14","domain":"Equation","prompt":"Which equation balances iron(III) oxide formation?","options":["2Fe + O₂ → Fe₂O₃","4Fe + 3O₂ → 2Fe₂O₃","3Fe + 2O₂ → Fe₃O₄","Fe + O₂ → Fe₂O₃"],"answer":1,"explanation":"The coefficients 4:3:2 balance Fe₂O₃ formation.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"model"},{"id":"u07-a-a15","domain":"Conservation","prompt":"Why is mass conserved in a closed ordinary chemical reaction?","options":["New nuclei are formed","Gas has no mass","The same atoms are rearranged into products","Energy becomes mass in large amounts"],"answer":2,"explanation":"Chemical reactions rearrange existing atoms.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"model"},{"id":"u07-a-a16","domain":"Measurement","prompt":"A gas-producing reaction loses measured mass in an open beaker. The best explanation is:","options":["Atoms were destroyed","The law of conservation failed","The liquid lost all density","Gas left the balance system"],"answer":3,"explanation":"The escaped product is no longer included in the measured system.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"quantitative"},{"id":"u07-a-a17","domain":"Reaction evidence","prompt":"Which observation alone is least sufficient to prove a chemical reaction?","options":["A temperature change without a control","A new precipitate with confirmed composition","A new gas product collected and identified","New products detected analytically"],"answer":0,"explanation":"Physical processes can also change temperature.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"evidence"},{"id":"u07-a-a18","domain":"Reaction type","prompt":"CH₄ + 2O₂ → CO₂ + 2H₂O is classified as:","options":["Freezing","Combustion","Precipitation","Electrolysis"],"answer":1,"explanation":"A hydrocarbon reacting with oxygen to form CO₂ and water is combustion.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a19","domain":"Energy","prompt":"Which sign belongs to an exothermic ΔH?","options":["Always zero","Undefined","Negative","Positive"],"answer":2,"explanation":"Products are lower in enthalpy than reactants under this convention.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a20","domain":"Energy","prompt":"Which process requires energy input?","options":["Making a chemical bond","Cooling surroundings during an exothermic reaction","Catalyst regeneration only","Breaking a chemical bond"],"answer":3,"explanation":"Bond breaking is endothermic.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a21","domain":"Catalyst","prompt":"Which statement about a catalyst is accurate?","options":["It lowers activation energy but does not change ΔH","It increases product energy","It is always consumed","It changes atom conservation"],"answer":0,"explanation":"Catalysts alter the pathway, not overall energy difference.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a22","domain":"Rate","prompt":"Increasing concentration usually increases rate because:","options":["The reaction becomes exothermic","More reactant particles occupy a given volume, increasing collision frequency","Particles become heavier","Activation energy disappears"],"answer":1,"explanation":"More particles per volume generally means more collisions.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"quantitative"},{"id":"u07-a-a23","domain":"Rate","prompt":"Why can higher temperature increase rate?","options":["All bonds disappear","Concentration becomes zero","More particles exceed activation energy","Subscripts change"],"answer":2,"explanation":"The energy distribution shifts so more collisions can succeed.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"quantitative"},{"id":"u07-a-a24","domain":"Rate","prompt":"Which design best isolates the effect of surface area?","options":["Use different masses and temperatures","Change three variables","Use one trial with no timing","Use equal tablet masses, equal water volume and temperature, changing only tablet size"],"answer":3,"explanation":"A fair comparison changes one factor while controlling others.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"quantitative"},{"id":"u07-a-a25","domain":"Rate data","prompt":"For equal reaction amounts, trial A finishes in 20 s and trial B in 50 s. Which is faster?","options":["Trial A","Trial B","They are equal","Cannot compare time"],"answer":0,"explanation":"The same extent of reaction occurs sooner in A.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"quantitative"},{"id":"u07-a-a26","domain":"Equilibrium","prompt":"At dynamic equilibrium:","options":["Only products remain","Forward and reverse rates are equal","Concentrations must be numerically equal","All molecules stop moving"],"answer":1,"explanation":"Equal rates maintain constant concentrations.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"model"},{"id":"u07-a-a27","domain":"Equilibrium","prompt":"What does a catalyst do to an equilibrium system?","options":["It changes ΔH","It changes the equilibrium constant at fixed temperature","It helps both directions reach equilibrium faster without changing the equilibrium position","It forces only products"],"answer":2,"explanation":"The catalyst lowers barriers for both directions.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"model"},{"id":"u07-a-a28","domain":"Industry","prompt":"Why is a compromise temperature used in the Haber process?","options":["Temperature has no effect","Only the catalyst matters","Ammonia forms instantly","It balances reaction rate, equilibrium yield, energy use, and safety/economics"],"answer":3,"explanation":"Industrial conditions balance multiple constraints.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"},{"id":"u07-a-a29","domain":"Model limits","prompt":"Which statement is scientifically responsible?","options":["Ball-and-stick models show connectivity and shape but distort size and electron density","Models are exact photographs","Ionic solids are single molecules","The octet rule has no exceptions"],"answer":0,"explanation":"Models are useful but simplified.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"model"},{"id":"u07-a-a30","domain":"Safety","prompt":"Which action is prohibited?","options":["Analyzing balanced equations","Mixing household cleaners to look for a reaction","Using published thermochemical data","Timing an approved effervescent tablet in water with goggles"],"answer":1,"explanation":"Household cleaners can generate toxic gases or corrosive mixtures.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment","type":"concept"}];
